  1	// Root documentary endpoint guard. No subprocess, submitted-code import, or grant.
  2	'use strict';
  3	const fs=require('fs'), path=require('path'), crypto=require('crypto'), util=require('util');
  4	const ROOT='/root/autodl-tmp/symbolic_dynamics';
  5	const QA=ROOT+'/docs/papers211_215_sequence/qa';
  6	const PREP=QA+'/p211_terminal_enable_preparation01';
  7	const DEST=QA+'/p211_terminal_enable_root01';
  8	const SELF=DEST+'/entry_source01/precheck.js';
  9	const ENV4={PATH:'/usr/bin:/bin',LANG:'C.UTF-8',LC_ALL:'C.UTF-8',TZ:'UTC'};
 10	const FIELDS=['dev','ino','mode','nlink','uid','gid','size','mtimeNs','ctimeNs'];
 11	let checks=0, reads={}, host=new Set();
 12	function need(v,s){checks++;if(!v)throw Error(s)}
 13	function equal(a,b,s){need(util.isDeepStrictEqual(a,b),s)}
 14	function pin(b){return {bytes:b.length,sha256:crypto.createHash('sha256').update(b).digest('hex')}}
 15	function stat(s){return Object.fromEntries(FIELDS.map(k=>[k,s[k].toString()]))}
 16	function exists(p){try{fs.lstatSync(p);return true}catch(e){if(e.code==='ENOENT'||e.code==='ENOTDIR')return false;throw e}}
 17	function physical(p){
 18	  if(exists(p))return fs.realpathSync(p);
 19	  let parent=path.dirname(p);need(parent!==p,'resolvable absent ancestor');
 20	  return path.join(physical(parent),path.basename(p));
 21	}
 22	function read(p){
 23	  need(path.isAbsolute(p)&&(p.startsWith(ROOT+'/')||host.has(p)),'predeclared input '+p);
 24	  let ls=fs.lstatSync(p,{bigint:true}),s=fs.statSync(p,{bigint:true});
 25	  need(s.isFile(),'regular resolved file '+p);
 26	  let resolved=fs.realpathSync(p),symlink=ls.isSymbolicLink()?fs.readlinkSync(p):null;
 27	  if(p.startsWith(ROOT+'/'))need(resolved===p&&symlink===null,'physical workspace '+p);
 28	  let raw=fs.readFileSync(p),v={...pin(raw),resolved,symlink,stat:stat(s),lstat:stat(ls)};
 29	  equal(stat(fs.statSync(p,{bigint:true})),v.stat,'stable stat '+p);
 30	  equal(stat(fs.lstatSync(p,{bigint:true})),v.lstat,'stable lstat '+p);
 31	  need(fs.realpathSync(p)===resolved&&BigInt(raw.length)===s.size,'stable whole bytes '+p);
 32	  if(reads[p])equal(v,reads[p],'repeat rich input '+p);
 33	  reads[p]=v;return raw;
 34	}
 35	function obj(p){return JSON.parse(read(p))}
 36	function reference(r){equal(pin(read(r.path)),r.pin,'exact reference '+r.path);return r.path}
 37	function entry(p,members=false){
 38	  need(p.startsWith(ROOT+'/')||host.has(p),'predeclared configuration '+p);
 39	  let present=exists(p),symlink=present&&fs.lstatSync(p).isSymbolicLink();
 40	  let v={path:p,present,symlink,resolved:physical(p)};
 41	  if(symlink)v.link=fs.readlinkSync(p);
 42	  if(present){let s=fs.statSync(p,{bigint:true});
 43	    if(s.isFile())Object.assign(v,{kind:'file'},pin(read(p)));
 44	    else if(s.isDirectory()){v.kind='directory';if(members)v.members=fs.readdirSync(p).sort()}
 45	    else if(s.isCharacterDevice()){
 46	      let d=s.rdev;Object.assign(v,{kind:'character_device',major:Number(((d>>8n)&0xfffn)|((d>>32n)&0xfffff000n)),minor:Number((d&0xffn)|((d>>12n)&0xffffff00n))});
 47	    }else Object.assign(v,{kind:'other',mode:Number(s.mode&0o170000n)});
 48	  }return v;
 49	}
 50	function tree(base){
 51	  need(fs.statSync(base).isDirectory()&&!fs.lstatSync(base).isSymbolicLink()&&fs.realpathSync(base)===base,'physical package');
 52	  let files=[],directories=[],ids=new Set();
 53	  function walk(dir){for(let name of fs.readdirSync(dir).sort()){
 54	    let p=dir+'/'+name,s=fs.lstatSync(p,{bigint:true}),n=path.relative(base,p);
 55	    need(!s.isSymbolicLink(),'no package symlink');
 56	    if(s.isDirectory()){directories.push(n);walk(p)}
 57	    else{need(s.isFile()&&s.nlink===1n&&!ids.has(s.dev+':'+s.ino),'ordinary distinct payload');ids.add(s.dev+':'+s.ino);files.push(n)}
 58	  }}walk(base);return {files:files.sort(),directories:directories.sort()};
 59	}
 60	function seal(base){
 61	  let lines=read(base+'/SHA256SUMS').toString().trimEnd().split('\n'),names=[],rows={};
 62	  for(let line of lines){let m=/^([0-9a-f]{64})  (.+)$/.exec(line);need(!!m,'seal grammar');
 63	    let n=m[2];need(n!=='SHA256SUMS'&&!path.isAbsolute(n)&&!n.split('/').some(x=>['','.','..'].includes(x))&&!rows[n],'safe unique nonself');
 64	    need(pin(read(base+'/'+n)).sha256===m[1],'entire seal payload');rows[n]=m[1];names.push(n);
 65	  }
 66	  equal(names,[...names].sort(),'sorted seal');let dirs=new Set();for(let n of names){let d=path.dirname(n);while(d!=='.'){dirs.add(d);d=path.dirname(d)}}
 67	  equal(tree(base),{files:names.concat('SHA256SUMS').sort(),directories:[...dirs].sort()},'whole seal membership');return names.length;
 68	}
 69	function put(dir,name,value){let raw=Buffer.from(JSON.stringify(value,null,2)+'\n');fs.writeFileSync(dir+'/'+name,raw,{flag:'wx',mode:0o600});return pin(raw)}
 70	function main(){
 71	  const [mode,phase,num]=process.argv.slice(2);
 72	  need(process.argv.length===5&&['before','after'].includes(mode)&&['refresh','enable','capture'].includes(phase)&&['1','2'].includes(num),'literal mode/phase/build');
 73	  need(process.cwd()===ROOT&&process.argv[1]===SELF,'literal root/source');equal({...process.env},ENV4,'exact documentary ENV4');
 74	  const plan=obj(PREP+'/INPUT_PLAN.json');equal(pin(read(PREP+'/INPUT_PLAN.json')),{bytes:94596,sha256:'4e41d0c20016e9d331a7faf22cc683dad3fbedd00288d935fbff55ad343394a3'},'accepted plan');
 75	  equal(pin(read(PREP+'/terminal_control.py')),{bytes:41305,sha256:'238369a33404a06ee4789af4bb7afd447213d70c21266b72cdca5d4a047ecea4'},'accepted unchanged controller');
 76	  equal(pin(read(DEST+'/SOURCE_RECEPTION.md')),{bytes:5765,sha256:'a49d0145e184af65c976e2a199fb91c9ee560774a11482686fc93ce872e406f4'},'accepted source gate');
 77	  read(SELF);read(DEST+'/entry_source01/SOURCE_RECEPTION.md');
 78	  let hs=obj(PREP+'/HOST_SCOPE.json');need(hs.entries===841&&hs.paths.length===841,'exact host scope');host=new Set(hs.paths);
 79	  for(let r of Object.values(plan.dependency_references))reference(r);
 80	  let old=obj(plan.dependency_references.original_lock.path),key=obj(plan.dependency_references.prior_read_key.path),config=obj(plan.dependency_references.prior_configuration_key.path);
 81	  let mapping=Object.fromEntries(obj(plan.dependency_references.historical_mapping.path).map(r=>[r.logical_path,r]));
 82	  need(Object.keys(key).length===1299&&Object.keys(config).length===843&&Object.keys(old.entries).length===840,'full fixed scopes');
 83	  let selected={},current={};
 84	  for(let [p,spec]of Object.entries(old.selector_specs)){selected[p]=entry(p,!!spec.members);equal(selected[p],old.entries[p],'whole selector '+p)}
 85	  for(let [p,v]of Object.entries(config)){current[p]=entry(p,'members' in v);equal(current[p],v,'whole historical configuration '+p)}
 86	  let substitutions={};
 87	  for(let [p,v]of Object.entries(key)){let target=p;if(mapping[p]){equal(mapping[p].pin,v,'original mapping pin');target=mapping[p].physical_original;substitutions[p]=target}equal(pin(read(target)),v,'full inherited byte key '+p)}
 88	  equal(substitutions,plan.exact_historical_substitutions,'only two physical historical substitutions');
 89	  need(Object.keys(plan.workspace_input_pins).length===272,'all272 planned originals');for(let [p,v]of Object.entries(plan.workspace_input_pins))equal(pin(read(p)),v,'planned original '+p);
 90	  for(let [p,t]of Object.entries(plan.exact_input_package_trees))equal(tree(p),{files:[...t.files].sort(),directories:[...t.directories].sort()},'complete accepted input package '+p);
 91	  need(seal(PREP)===9,'preparation9');need(seal(QA+'/p211_initial_build_01')===362,'oldbuild362');need(seal(QA+'/p211_initial_build_independent_reception')===18,'oldaudit18');need(seal(ROOT+'/papers/211-kernel-image-projection-feedback/frozen_round0')===32,'oldfreeze32');
 92	  const b=plan.builds[num],authority=b.authority_paths[phase],phaseDir=b.phase_outputs[phase],dest=b.root_parent+'/'+phase+'_entry01';
 93	  let authorityRaw=read(authority).toString(),blocks=[...authorityRaw.matchAll(/^```json\n([\s\S]*?)\n```$/gm)];need(blocks.length===1,'one actual root grant');let grant=JSON.parse(blocks[0][1]);
 94	  need(grant.issuer==='/root'&&grant.phase===phase&&grant.build_number===Number(num)&&grant.phase_output===phaseDir&&grant.cold_output===b.cold_output,'actual scoped root authority');
 95	  reference(grant.controller);reference(grant.input_plan);reference(grant.preparation_seal);for(let r of Object.values(grant.required_receipts))reference(r);
 96	  equal(grant.controller_environment,ENV4,'grant environment');
 97	  need(fs.statSync(b.root_parent).isDirectory()&&fs.realpathSync(b.root_parent)===b.root_parent,'ordinary root parent');
 98	  const finalParent=path.dirname(b.cold_output);need(fs.statSync(finalParent).isDirectory()&&fs.realpathSync(finalParent)===finalParent&&!fs.lstatSync(finalParent).isSymbolicLink(),'ordinary separately created qa_final');
 99	  let absent=[phaseDir+'/unused_controller_cache',b.outer_pycache_prefix,b.inner_pycache_prefix,...b.cwd_relative_paths];
100	  if(mode==='before'||phase!=='capture')absent.push(b.cold_output);
101	  if(mode==='before'){absent.push(phaseDir);need(!exists(dest),'new literal entry packet');}
102	  const absences={};for(let p of absent){need(!exists(p)&&physical(p)===p,'exact future absence '+p);absences[p]={present:false,resolved:p}}
103	  const argv=['/usr/bin/python3.10','-I','-S','-B','-X','pycache_prefix='+phaseDir+'/unused_controller_cache',PREP+'/terminal_control.py',phase,num,authority,String(Buffer.byteLength(authorityRaw)),pin(Buffer.from(authorityRaw)).sha256];
104	  for(let p of ['/usr/bin/python3.10','/usr/bin/env','/usr/bin/bash','/dev/null'])need(host.has(p),'inherited product/controller launch spelling '+p);
105	  if(mode==='before')fs.mkdirSync(dest,{mode:0o700});
106	  else{
107	    let native=JSON.parse(fs.readFileSync(dest+'/CONTROLLER_TOOL_NATIVE.json'));
108	    need(native.results.length>=1&&native.results.at(-1).exit_code!==undefined&&!('session_id' in native.results.at(-1)),'actual settled product completion before endpoint closure');
109	    let prev=JSON.parse(fs.readFileSync(dest+'/INPUTS_BEFORE.json'));
110	    equal(reads,prev,'all exact byte/stat inputs unchanged across actual controller');
111	    let previous=JSON.parse(fs.readFileSync(dest+'/CONFIGURATION_BEFORE.json'));equal({selected,current},{selected:previous.selected,current:previous.current},'all840/843 configuration endpoints');
112	  }
113	  let suffix=mode.toUpperCase(),configuration={selected,current,absences};
114	  const outputs={inputs:put(dest,'INPUTS_'+suffix+'.json',reads),configuration:put(dest,'CONFIGURATION_'+suffix+'.json',configuration)};
115	  let result={status:'PASS_ROOT_'+suffix+'_CONTROLLER_ENDPOINT_CHECK',phase,build_number:Number(num),checks,read_paths:Object.keys(reads).length,host_scope:841,inherited_files:1299,selector:840,configuration:843,planned_originals:272,argv,environment:ENV4,cwd:ROOT,authority:pin(Buffer.from(authorityRaw)),outputs,new_controller_invocations:0,new_science:0,new_builds:0,source_only_diagnostic_runtime:{node:process.version,execPath:process.execPath,os_trace:false},limits:'Metadata endpoint guard; no scientific/TeX execution, no host discovery, no authority or acceptance, and no continuous startup/process trace.'};
116	  const resultPin=put(dest,'RESULT_'+suffix+'.json',result);console.log(JSON.stringify({status:result.status,checks,result:{path:dest+'/RESULT_'+suffix+'.json',pin:resultPin},read_paths:result.read_paths,argv,new_controller_invocations:0}));
117	}
118	try{main()}catch(e){console.error(e.stack);process.exitCode=1}
